/*
    一括WFのステート、資料分類で表示内容変更
    資料分類に対応するタブのみ表示
    (開達書式のように途中で資料分類が変わることはないので作業中判定不要)
*/
const CLN = "h4_AppWFGrForDATFormat CLN";
const EXPCLN = "h4_AppWFGrForDATFormat EXPCLN";

const InProgress = "InProgress";//作業中ステート

// メイン処理
controlTabs();

function controlTabs() {
    if (!parent.relationships)
      {
        setTimeout(controlTabs, 50);
        return;
      }
    var tabbar = parent.relationships.relTabbar;
    var topWnd = aras.getMostTopWindowWithAras(window);
    var topItem = topWnd.thisItem;
    
    //資料分類の取得
    var isEXPIntSt = topItem.getProperty("h4_isexp", "");
    
    // TABIDはリレーションシップタイプアイテムのID
    // 単数用のサインオフタブ
    var tabIdSO1 //担当者通常
    var tabIdSO2 //担当者EXP
    tabIdSO1 = getTabID(CLN);
    tabIdSO2 = getTabID(EXPCLN);

    if(isEXPIntSt == "1")
    {
        //作業中以外、EXPTest
        tabbar.SetTabVisible(tabIdSO1, false);
        tabbar.SetTabVisible(tabIdSO2, true);

        return;
    }
    else
    {
        //作業中以外、EXPTest以外
        tabbar.SetTabVisible(tabIdSO1, true);
        tabbar.SetTabVisible(tabIdSO2, false);

        return;
    }
}

// RelationshipTypeアイテムの名前からIDを取得する
function getTabID(name){
    var rel = aras.newIOMItem("RelationshipType", "get");
    rel.setProperty("name", name);
    rel = rel.apply();
    return rel.getID();
};
